var D_MANCO = l2("2\u20132.5 g per litre of water", "\u09AA\u09CD\u09B0\u09A4\u09BF \u09B2\u09BF\u099F\u09BE\u09B0 \u09AA\u09BE\u09A8\u09BF\u09A4\u09C7 \u09E8\u2013\u09E8.\u09EB \u0997\u09CD\u09B0\u09BE\u09AE");
