function buildDiseases() {
  let treatmentId = 1;
  const all = [
    ...DEFS.map((d2) => ({ ...d2, classLabel: d2.label, images: diseaseImages(d2.label) })),
    ...EXTRA_DEFS.map((d2) => ({ ...d2, classLabel: `${d2.model}:${d2.label}`, images: [] }))
  ];
  return all.map((d2, index) => ({
    id: index + 1,
    class_label: d2.classLabel,
    crop: cropByKey(d2.crop),
    name: d2.name,
    type: d2.type,
    is_healthy: d2.type === "healthy",
    pathogen: d2.pathogen,
    images: d2.images,
    symptoms: d2.symptoms,
    causes: d2.causes,
    treatments: d2.treatments.map((t) => ({ ...t, id: treatmentId++ }))
  }));
}
var MODEL_LABELS = DEFS.map((d2) => d2.label);

// scripts/export-seed.ts
var here = dirname(fileURLToPath(import.meta.url));
var outDir = resolve(here, "../../backend/app/seed");
mkdirSync(outDir, { recursive: true });
var diseases = buildDiseases().map((d2) => ({
  id: d2.id,
  class_label: d2.class_label,
  crop_key: d2.crop.key,
  name: d2.name,
  type: d2.type,
  is_healthy: d2.is_healthy,
  pathogen: d2.pathogen ?? null,
  symptoms: d2.symptoms,
  causes: d2.causes,
  treatments: d2.treatments.map((t) => ({ type: t.type, remedy: t.remedy, dosage: t.dosage ?? null, precautions: t.precautions ?? null }))
}));
writeFileSync(resolve(outDir, "crops.json"), JSON.stringify(CROPS, null, 2) + "\n", "utf8");
writeFileSync(resolve(outDir, "diseases.json"), JSON.stringify(diseases, null, 2) + "\n", "utf8");
console.log(`Wrote ${CROPS.length} crops and ${diseases.length} diseases (${MODEL_LABELS.length} main-model labels) to ${outDir}`);
